package com.retail.transfers;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import com.retail.common.security.BranchAccess;
import com.retail.common.audit.AuditService;
@RestController @RequestMapping("/api/v1/transfers")
public class TransferController {
 private final JdbcTemplate jdbc;private final BranchAccess access;private final AuditService audit;public TransferController(JdbcTemplate j,BranchAccess a,AuditService audit){jdbc=j;access=a;this.audit=audit;}
 public record Line(@NotNull UUID productId,@Min(1) int quantity){} public record Request(@NotNull UUID sourceLocationId,@NotNull UUID destinationLocationId,@NotEmpty List<@Valid Line> lines){}
 @PostMapping @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER','INVENTORY_STAFF')") public Map<String,Object> create(@Valid @RequestBody Request r,@RequestHeader("Idempotency-Key") String key,Authentication a){if(r.sourceLocationId().equals(r.destinationLocationId()))throw new IllegalArgumentException("Transfer locations must differ");var src=jdbc.queryForMap("select * from locations where id=?",r.sourceLocationId());var dst=jdbc.queryForMap("select * from locations where id=?",r.destinationLocationId());if(src.get("branch_id")!=null)access.requireBranch(a,(UUID)src.get("branch_id"));if(dst.get("branch_id")!=null)access.requireBranch(a,(UUID)dst.get("branch_id"));var exists=jdbc.queryForList("select id,transfer_no from stock_transfers where idempotency_key=?",key);if(!exists.isEmpty())return exists.getFirst();UUID id=UUID.randomUUID();String no="TR-"+id.toString().substring(0,12).toUpperCase(Locale.ROOT);UUID user=jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName());jdbc.update("insert into stock_transfers(id,transfer_no,source_location_id,destination_location_id,status,idempotency_key,created_by) values (?,?,?,?,'PENDING',?,?)",id,no,r.sourceLocationId(),r.destinationLocationId(),key,user);for(Line l:r.lines())jdbc.update("insert into stock_transfer_lines(transfer_id,product_id,quantity) values (?,?,?)",id,l.productId(),l.quantity());audit.record(a.getName(),"TRANSFER_CREATED","STOCK_TRANSFER",id,null);return Map.of("id",id,"transferNo",no,"status","PENDING");}
 @PostMapping("/{id}/approve") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER')") public Map<String,Object> approve(@PathVariable UUID id,Authentication a){var t=load(id);scope(t,a);transition(id,"PENDING","APPROVED","approved_by",a);audit.record(a.getName(),"TRANSFER_APPROVED","STOCK_TRANSFER",id,null);return Map.of("id",id,"status","APPROVED");}
 @PostMapping("/{id}/dispatch") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','INVENTORY_STAFF','BRANCH_MANAGER')") public Map<String,Object> dispatch(@PathVariable UUID id,Authentication a){var t=load(id);scope(t,a);if(!"APPROVED".equals(t.get("status")))throw new IllegalStateException("Transfer must be approved");var source=jdbc.queryForMap("select type from locations where id=?",t.get("source_location_id"));if("CENTRAL_WAREHOUSE".equals(source.get("type"))&&!access.global(a)&&a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_INVENTORY_STAFF")))throw new org.springframework.security.access.AccessDeniedException("Warehouse dispatch permission required");UUID transit=jdbc.queryForObject("select id from locations where type='IN_TRANSIT' limit 1",UUID.class);UUID actor=actor(a);for(var l:jdbc.queryForList("select * from stock_transfer_lines where transfer_id=? order by product_id for update",id)){UUID product=(UUID)l.get("product_id");int qty=(Integer)l.get("quantity");int n=jdbc.update("update stock_balances set quantity=quantity-?,version=version+1 where location_id=? and product_id=? and quantity>=?",qty,t.get("source_location_id"),product,qty);if(n!=1)throw new IllegalStateException("Insufficient source stock");jdbc.update("insert into stock_balances(location_id,product_id,quantity) values (?,?,?) on conflict(location_id,product_id) do update set quantity=stock_balances.quantity+excluded.quantity,version=stock_balances.version+1",transit,product,qty);movement(t.get("source_location_id"),product,-qty,"TRANSFER_DISPATCH",id,actor);movement(transit,product,qty,"TRANSFER_DISPATCH",id,actor);}jdbc.update("update stock_transfers set status='IN_TRANSIT',dispatched_by=?,dispatched_at=now() where id=?",actor,id);audit.record(a.getName(),"TRANSFER_DISPATCHED","STOCK_TRANSFER",id,null);return Map.of("id",id,"status","IN_TRANSIT");}
 @PostMapping("/{id}/receive") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','INVENTORY_STAFF','BRANCH_MANAGER')") public Map<String,Object> receive(@PathVariable UUID id,Authentication a){var t=load(id);scope(t,a);if(!"IN_TRANSIT".equals(t.get("status")))throw new IllegalStateException("Transfer is not in transit");UUID transit=jdbc.queryForObject("select id from locations where type='IN_TRANSIT' limit 1",UUID.class);UUID actor=actor(a);for(var l:jdbc.queryForList("select * from stock_transfer_lines where transfer_id=? order by product_id for update",id)){UUID product=(UUID)l.get("product_id");int qty=(Integer)l.get("quantity");int n=jdbc.update("update stock_balances set quantity=quantity-?,version=version+1 where location_id=? and product_id=? and quantity>=?",qty,transit,product,qty);if(n!=1)throw new IllegalStateException("In-transit stock is unavailable");jdbc.update("insert into stock_balances(location_id,product_id,quantity) values (?,?,?) on conflict(location_id,product_id) do update set quantity=stock_balances.quantity+excluded.quantity,version=stock_balances.version+1",t.get("destination_location_id"),product,qty);movement(transit,product,-qty,"TRANSFER_RECEIPT",id,actor);movement(t.get("destination_location_id"),product,qty,"TRANSFER_RECEIPT",id,actor);}jdbc.update("update stock_transfers set status='RECEIVED',received_by=?,received_at=now() where id=?",actor,id);audit.record(a.getName(),"TRANSFER_RECEIVED","STOCK_TRANSFER",id,null);return Map.of("id",id,"status","RECEIVED");}
 @PostMapping("/{id}/cancel") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER')") public Map<String,Object> cancel(@PathVariable UUID id,Authentication a){var t=load(id);scope(t,a);if(!Set.of("PENDING","APPROVED").contains(t.get("status")))throw new IllegalStateException("Dispatched transfers cannot be cancelled");jdbc.update("update stock_transfers set status='CANCELLED' where id=?",id);audit.record(a.getName(),"TRANSFER_CANCELLED","STOCK_TRANSFER",id,null);return Map.of("id",id,"status","CANCELLED");}
 private Map<String,Object> load(UUID id){return jdbc.queryForMap("select * from stock_transfers where id=? for update",id);}private UUID actor(Authentication a){return jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName());}private void scope(Map<String,Object> t,Authentication a){for(String k:List.of("source_location_id","destination_location_id")){UUID loc=(UUID)t.get(k);var row=jdbc.queryForMap("select branch_id from locations where id=?",loc);if(row.get("branch_id")!=null)access.requireBranch(a,(UUID)row.get("branch_id"));}}private void transition(UUID id,String from,String to,String col,Authentication a){if(!from.equals(load(id).get("status")))throw new IllegalStateException("Invalid transfer state");jdbc.update("update stock_transfers set status=?,"+col+"=? where id=?",to,actor(a),id);}private void movement(Object loc,UUID product,int qty,String type,UUID id,UUID actor){jdbc.update("insert into stock_movements(location_id,product_id,quantity_delta,movement_type,source_type,source_id,actor_id) values (?,?,?,?,?,?,?)",loc,product,qty,type,"TRANSFER",id,actor);}
}


